<template>
  <ShopBanner v-if="ConfigShowShopBanner"/>
  <v-app id="layout-app">
    <v-app-bar density="comfortable" :color="ConfigTopbarColor" :elevation="0" class="border-b">
      <v-app-bar-nav-icon variant="text" @click.stop="drawer=!drawer"/>
      <v-spacer/>
      <HelperIcon/>
      <CopierCart/>
      <div class="ml-3 mr-3"></div>
      <Branding/>
    </v-app-bar>
    <v-navigation-drawer width="300" v-model="drawer" location="left">
      <v-card elevation="0" class="pa-5">
        <v-card-text class="pa-3">
          <v-text-field
            prepend-inner-icon="mdi-magnify"
            v-model="SearchBox"
            class="search-box"
            variant="outlined"
            bg-color="#F8F8F8"
            density="compact"
            label="Search"
            type="search"
            rounded="lg">
          </v-text-field>

          <FilterItem :hide-button="true">
            <template #title>
              <div class="d-flex justify-space-between align-center mb-1">
                <div>Filters</div>
                <div>
                  <v-btn
                    text="Reset"
                    size="x-small"
                    class="d-flex"
                    color="primary"
                    variant="outlined"
                    @click="ResetFilters"
                    v-if="HasActiveFilters"
                    prepend-icon="mdi-restart">
                  </v-btn>
                </div>
              </div>
            </template>
            <FilterTags/>
          </FilterItem>

          <v-divider/>

          <FilterItem title="Manufacturer">
            <CustomCheckbox
              :label="make.name"
              v-for="(make) in manufacturers.filter(man => manufacturers_allowed.includes(man.id))"
              @CheckChange="SetAnyFilter($event,'manufacturers',+make.id)"
              :is_checked="ItemExists('manufacturers',+make.id)">
            </CustomCheckbox>
          </FilterItem>

          <v-divider/>

          <FilterItem title="Product Category">
            <CustomCheckbox
              :label="category"
              v-for="category in printer_categories"
              @CheckChange="SetAnyFilter($event,'product_categories',category)"
              :is_checked="ItemExists('product_categories',category)">
            </CustomCheckbox>
          </FilterItem>

          <v-divider/>

          <FilterItem title="Intended Use">
            <CustomCheckbox
              :label="level"
              v-for="level in usage_levels"
              @CheckChange="SetAnyFilter($event,'usage_levels',level)"
              :is_checked="ItemExists('usage_levels',level)">
            </CustomCheckbox>
          </FilterItem>

          <v-divider/>

          <FilterItem title="Mono or Color">
            <CustomCheckbox label="Color" @CheckChange="SetAnyFilter($event,'copier_colors','Color')" :is_checked="ItemExists('copier_colors','Color')"/>
            <CustomCheckbox label="Mono" @CheckChange="SetAnyFilter($event,'copier_colors','B&W')" :is_checked="ItemExists('copier_colors','B&W')"/>
          </FilterItem>

          <v-divider/>

          <FilterItem title="Form Factor">
            <CustomCheckbox
              :label="form_factor"
              v-for="form_factor in form_factors"
              @CheckChange="SetAnyFilter($event,'form_factors',form_factor)"
              :is_checked="ItemExists('form_factors',form_factor)">
            </CustomCheckbox>
          </FilterItem>

          <v-divider/>

          <FilterItem title="Capabilities">
            <CustomCheckbox
              :label="capability"
              v-for="capability in capabilities"
              @CheckChange="SetAnyFilter($event,'capabilities',capability)"
              :is_checked="ItemExists('capabilities',capability)">
            </CustomCheckbox>
          </FilterItem>

          <v-divider/>

          <FilterItem title="Connectivity">
            <CustomCheckbox
              :label="connection"
              v-for="connection in connection_types"
              @CheckChange="SetAnyFilter($event,'connection_types',connection)"
              :is_checked="ItemExists('connection_types',connection)">
            </CustomCheckbox>
          </FilterItem>

          <v-divider/>

          <FilterItem title="Speed (PPM)">
            <v-row>
              <v-col cols="12" lg="6" md="6" sm="12">
                <v-text-field @input="SetSpeedMin" :model-value="filters.speed_minimum" rounded="lg" type="number" variant="outlined" density="compact" label="Min" placeholder="min"/>
              </v-col>
              <v-col cols="12" lg="6" md="6" sm="12">
                <v-text-field @input="SetSpeedMax" :model-value="filters.speed_maximum" rounded="lg" type="number" variant="outlined" density="compact" label="Max" placeholder="max"/>
              </v-col>
            </v-row>
          </FilterItem>

          <v-divider/>

          <FilterItem title="Paper Size">
            <CustomCheckbox
              :label="paper_size"
              v-for="paper_size in paper_sizes"
              :is_checked="ItemExists('paper_sizes',paper_size)"
              @CheckChange="SetAnyFilter($event,'paper_sizes',paper_size)">
            </CustomCheckbox>
          </FilterItem>
        </v-card-text>
      </v-card>
    </v-navigation-drawer>
    <v-main>
      <v-card-text class="pa-1 pa-sm-3 pa-md-5" style="background:#f1f1f1">
        <slot name="content"/>
      </v-card-text>
      <v-footer v-if="$slots.footer" style="background:#f1f1f1" elevation="1">
        <slot name="footer"/>
      </v-footer>
    </v-main>
  </v-app>
</template>

<script>
import {mapActions, mapState} from "vuex";
import {CommonMixins} from "@/mixins/CommonMixins";
import CopierCart from "@/components/configurator/CopierCart.vue";
import HelperIcon from "@/components/configurator/HelperIcon.vue";
import CustomCheckbox from "@/components/typography/CustomCheckbox.vue";
import FilterTags from "@/components/catalog/FilterTags.vue";
import FilterItem from "@/components/catalog/FilterItem.vue";
import Branding from "@/components/misc/Branding.vue";
import ShopBanner from "@/components/catalog/ShopBanner.vue";

export default {
  mixins: [CommonMixins],
  components: {ShopBanner, Branding, FilterTags, HelperIcon, CustomCheckbox, CopierCart, FilterItem},
  data: () => ({
    drawer: true,
    is_logged_in: false,
    profile: null,
    controls: {
      brands: false,
    }
  }),
  methods: {
    ...mapActions(['SetFilters', 'SetAnyState']),
    SetSpeedMin(event) {
      const filters = {...this.filters};
      filters.speed_minimum = +event.target.value;
      if (event.target.value.length < 1) filters.speed_minimum = null;
      this.SetFilters(filters);
    },
    SetSpeedMax(event) {
      const filters = {...this.filters};
      filters.speed_maximum = +event.target.value;
      if (event.target.value.length < 1) filters.speed_maximum = null;
      this.SetFilters(filters);
    },
    SetAnyFilter(is_checked, target, value) {
      if (typeof is_checked == "object") {
        is_checked = is_checked.target.checked;
      }
      const rawFilters = {...this.filters};
      const exists = rawFilters[target].find(c => c == value);
      if (is_checked == true) {
        if (!exists) {
          rawFilters[target].push(value);
        }
      } else {
        if (exists) {
          const index = rawFilters[target].indexOf(value);
          if (index !== -1) {
            rawFilters[target].splice(index, 1);
          }
        }
      }
      this.SetFilters(rawFilters);
      this.$forceUpdate();
    },
    ItemExists(target, value) {
      return this.filters[target].includes(value);
    },
    ResetFilters() {
      this.SetAnyState({target:'filters', value:{
        sort_type: null,
        page_limit: 12,
        search_input: '',
        manufacturers: [],
        device_types: [],
        copier_colors: [],
        speed_minimum: null,
        speed_maximum: null,
        price_filters: [],
        price_options: [
          {
            label: "$69-$99",
            min: 69,
            max: 99
          },
          {
            label: "$100-$199",
            min: 100,
            max: 199
          },
          {
            label: "$200+",
            min: 200,
            max: 9999
          }
        ],

        // New Filters
        paper_sizes: [],
        product_categories: [],
        form_factors: [],
        capabilities: [],
        connection_types: [],
        usage_levels: [],
      }});
    },
  },
  mounted() {
    // Set defaults for drawers on small screens
    const isMobile = window.innerWidth <= 768;
    if (isMobile) {
      this.drawer = false;
      this.SetAnyState({target: 'config_drawer', value: false});
      this.SetAnyState({target: 'is_mobile', value: isMobile});
    }
  },
  computed: {
    ...mapState([
      'products',
      'filters',
      'manufacturers',
      'manufacturers_allowed',
      'catalog_page_title',
      'settings',

      // Filters
      'printer_categories',
      'paper_sizes',
      'connection_types',
      'media_types',
      'form_factors',
      'capabilities',
      'usage_levels',
    ]),
    SearchBox: {
      get() {
        return this.filters.search_input;
      },
      set(value) {
        const filters = {...this.filters}
        filters.search_input = value;
        this.SetFilters(filters);
      }
    },
    HasActiveFilters() {
      const { manufacturers, device_types, copier_colors, price_filters, paper_sizes, product_categories, form_factors, capabilities, connection_types, usage_levels, search_input, speed_minimum, speed_maximum } = this.filters;
      return [manufacturers, device_types, copier_colors, price_filters, paper_sizes, product_categories, form_factors, capabilities, connection_types, usage_levels].some(f => f.length > 0) || !!search_input || !!speed_minimum || !!speed_maximum
    },
  },
}
</script>
<style lang="scss">
#layout-app {
  .v-application__wrap {
    border-bottom: none !important;
    height: fit-content !important;
    margin-bottom: 0;
    min-height: 120vh;
  }
}
</style>
